from tests_src import T, Q2, TF

T(21, "21-7", "Helen Keller and Her Teacher", "Recount (Historical)", [
"Helen Keller was born in 1880 in a town called Tuscumbia, in the American state of Alabama. When she was very small, she lost both her sight and her hearing. It was very hard for her to tell her family what she wanted.",
"In March 1887, when Helen was nearly seven, a young teacher named Anne Sullivan came to live with the family. Anne could spell words on a person’s hand using her fingers. She gave Helen a doll and spelled the word d-o-l-l into Helen’s palm. Helen liked the doll, but she did not yet understand that the shapes Anne made with her fingers were words.",
"Then, on the 5th of April 1887, Anne took Helen outside to the water pump. She held one of Helen’s hands under the pump while the cool water splashed over it. With her other hand, Anne spelled the word w-a-t-e-r, first slowly and then quickly. At last, Helen understood that the shapes in her hand were the names of things.",
"After that, Helen wanted to know the name of everything she touched. Anne said that in just a few hours Helen had learned thirty new words, including door, open and give.",
"Helen kept learning for many years. She learned to read braille, which uses patterns of raised dots that can be read with the fingertips. She also learned to write and, with a great deal of practice, to speak.",
"Anne went to lessons with Helen and spelled out what the teachers said. In 1904, Helen finished her studies at a college called Radcliffe. She was the first person who was both blind and deaf to earn a university degree.",
"Helen went on to write more than a dozen books, and she travelled to many countries to give talks. Her story shows how much a person can achieve with a good teacher and plenty of patience.",
], [
 dict(d="2b",k="short",m=1,q="In which American state was Helen Keller born?",a="Alabama.",g="Accept Alabama."),
 dict(d="2b",k="short",m=1,q="What did Anne Sullivan give to Helen when she first arrived?",a="A doll.",g="Accept doll."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does the word “pump” most likely mean?",opts=["A machine that brings up water","A kind of toy for the garden","A gate at the end of a path","A bucket for carrying sand"],a="A"),
 dict(d="2b",k="find",m=1,q="Find and copy the word in paragraph 3 that tells you what the water felt like.",a="cool",g="Accept “cool” only."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Helen finished her studies at Radcliffe.","Helen learned thirty new words.","Anne spelled d-o-l-l into Helen’s palm.","Anne held Helen’s hand under the pump."],a=[4,3,1,2],g=Q2),
 dict(d="2d",k="short",m=1,q="Why did Helen find it hard to tell her family what she wanted?",a="She could not see or hear (and had no way of talking to them).",g="Accept any answer that mentions that she could not hear or see. Do not accept “she was too young”."),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Anne Sullivan came to live with the Keller family in 1887.","Helen learned the word water at a pump.","Braille is read with the eyes.","Helen wrote more than a dozen books."],a=["T","T","F","T"],g=TF),
 dict(d="2d",k="short",m=1,q="How can you tell that Helen understood something new at the water pump? Give one clue from paragraph 4.",a="Any one of: she wanted to know the name of everything she touched; she learned thirty new words.",g="Accept any one sensible clue."),
 dict(d="2d",k="short",m=1,q="Why do you think Anne spelled the word “water” while the water splashed over Helen’s hand?",a="So Helen could feel the water and connect it with the word.",g="Accept any answer linking the feeling of water to the word, so Helen could understand what the word meant."),
 dict(d="2d",k="mc",m=1,q="Which word best describes Anne Sullivan?",opts=["Impatient","Forgetful","Shy","Patient"],a="D"),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["Helen Keller was born in Alabama in the year 1880.","Helen Keller learned to communicate and achieved much with her teacher’s help.","Anne Sullivan liked to teach Helen by using a doll.","Braille is a way of reading with the fingertips."],a="B"),
])

T(22, "22-7", "Tenzing Norgay and the Top of the World", "Recount (Historical)", [
"Mount Everest is the highest mountain on Earth. It stands more than 8,800 metres above the sea, in the Himalayas, on the border between Nepal and Tibet. Near the top, the air is very thin, so it is hard to breathe.",
"The Sherpa people live in the mountains near Everest. They know the paths well and are used to the cold, thin air. Tenzing Norgay was a Sherpa mountaineer. As a young man in 1935, he joined his first expedition to Everest, and over the years that followed he went back to the mountain again and again. By 1953 he had been on six earlier expeditions and knew the mountain better than almost anyone.",
"In 1953, a British team came to Everest. Its leader was John Hunt, and the team wanted to climb all the way to the top, which nobody had ever managed. Tenzing was chosen as the lead Sherpa, which meant that he helped to look after the other Sherpas. Edmund Hillary, a mountaineer from New Zealand, was also on the team.",
"The team worked slowly and carefully. They set up a line of small camps higher and higher up the mountain, and they carried food, tents and air tanks up to each one. Everyone had a job to do, and every job mattered.",
"At last, the day came for Tenzing and Edmund to try for the top. They set off from their highest camp in the early morning. The final part was steep, so they had to help each other. They reached the top at half past 11 on the 29th of May 1953.",
"They stayed there for only about 15 minutes. Edmund took photographs, and Tenzing later wrote that he pushed some chocolate into the snow as a gift to the mountain, which the Sherpa people hold sacred. Then the two men began the long climb down.",
"Both climbers said that reaching the top had been a team effort. In 1954, Tenzing became a teacher at a new mountaineering school in Darjeeling, in India, where he trained young climbers for many years.",
], [
 dict(d="2b",k="short",m=1,q="In which year did Tenzing Norgay go on his first expedition to Everest?",a="1935.",g="Accept 1935."),
 dict(d="2a",k="mc",m=1,q="In paragraph 3, what does “expedition” mean?",opts=["A kind of hut where climbers can rest","A long journey made for a special purpose","A heavy bag for carrying food","A map showing the way up"],a="B"),
 dict(d="2b",k="short",m=1,q="Who led the British team in 1953?",a="John Hunt.",g="Accept John Hunt / Hunt."),
 dict(d="2b",k="find",m=1,q="Find and copy two words from paragraph 1 that tell you why it is hard to breathe near the top.",a="very thin",g="Accept “very thin” or “thin” (the air is very thin). Both words are not needed."),
 dict(d="2d",k="short",m=1,q="Why do you think Tenzing was chosen as the lead Sherpa?",a="He had a great deal of experience of Everest / had been on six earlier expeditions.",g="Accept any answer about his experience or knowing the mountain well."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Tenzing and Edmund reached the top of Everest.","Tenzing joined his first Everest expedition.","Tenzing became a teacher in Darjeeling.","The team set up camps higher up the mountain."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Everest is on the border between Nepal and Tibet.","Edmund Hillary was from New Zealand.","Tenzing and Edmund stayed at the top for about an hour.","Tenzing later taught young climbers."],a=["T","T","F","T"],g=TF),
 dict(d="2d",k="short",m=1,q="Paragraph 4 says, “Every job mattered.” What does this tell you about how the climb was done?",a="It was done by a whole team, with everyone doing their part.",g="Accept any answer about teamwork or everyone being needed."),
 dict(d="2d",k="short",m=1,q="The final part of the climb was steep, so the two men “had to help each other”. What does this suggest about the climb?",a="It was difficult / they needed to work together.",g="Accept any answer about difficulty, danger or teamwork."),
 dict(d="2b",k="short",m=1,q="What did Tenzing later write that he did at the top?",a="He pushed some chocolate into the snow as a gift to the mountain.",g="Accept chocolate / left a gift for the mountain."),
 dict(d="2d",k="mc",m=1,q="Why did the Sherpa people find it easier than most people to work high in the mountains?",opts=["They have very warm coats and boots.","They carry very little food or gear.","They know the paths and the cold air.","They had already been to the top."],a="C"),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the text?",opts=["Mount Everest is the highest mountain on Earth.","The team carried food and tents up the mountain.","Darjeeling is a town in the country of India.","Tenzing Norgay helped a team reach the top of Everest and later trained climbers."],a="D"),
])

T(23, "23-7", "Racing Down the Track", "Information Report", [
"Tanni Grey-Thompson is one of Britain’s most successful athletes. She was born in Cardiff, the capital city of Wales, in 1969. Tanni was born with a condition called spina bifida, which affects the spine and can make it difficult to walk. From the age of seven, she has used a wheelchair to get around.",
"Tanni loved sport as a child and began wheelchair racing when she was a teenager. A racing wheelchair is very different from the one used every day. It is long and light, with two large wheels at the back and usually a smaller one at the front. Racers sit low and push the wheels with special gloves to make them spin faster.",
"Wheelchair racing takes great strength and skill. Racers must build up powerful arms and shoulders, and they have to learn to steer at high speed. Tanni trained hard for many hours every week.",
"Her hard work paid off. In 1988, she went to the Paralympic Games in Seoul, where she won a bronze medal in the 400 metres. The Paralympic Games are a great sporting event for athletes with disabilities. Four years later, at the 1992 Games in Barcelona, she won four gold medals, in the 100, 200, 400 and 800 metre races.",
"Over her career, Tanni took part in five Paralympic Games. She won 16 medals altogether, and 11 of them were gold. She also won the London Marathon wheelchair race six times, and she set more than 30 world records. In 2004, at the Athens Games, she won two more gold medals in the 100 and 400 metre races.",
"Tanni also cared about helping others. She studied at university in England. Later she spoke up for disabled people, so that they could join in sport and everyday life more easily.",
"In 2005, she was made a Dame, an honour given by the King or Queen for outstanding work. Five years later, she joined the House of Lords, where politicians discuss and check the laws of the country. Tanni had gone from racing on the track to helping to shape the rules for everyone.",
"Many people see Tanni as an inspiring example. She has shown that with courage, practice and determination, a person can achieve remarkable things.",
], [
 dict(d="2b",k="short",m=1,q="In which city was Tanni Grey-Thompson born?",a="Cardiff.",g="Accept Cardiff."),
 dict(d="2a",k="mc",m=1,q="In paragraph 1, what does “spina bifida” mean, according to the text?",opts=["A kind of race for wheelchairs","A type of racing wheelchair","A condition that affects the spine","A prize given to sportspeople"],a="C"),
 dict(d="2b",k="find",m=1,q="Find and copy two words from paragraph 2 that describe a racing wheelchair.",a="long and light",g="Accept “long” and “light” (in either order or together)."),
 dict(d="2b",k="short",m=1,q="What do racers use to push the wheels?",a="Special gloves.",g="Accept gloves."),
 dict(d="2d",k="short",m=1,q="Why do you think racers must build powerful arms and shoulders?",a="They push the wheels with their arms to go fast.",g="Accept any answer linking arm strength to pushing the chair."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Tanni won four gold medals in Barcelona.","Tanni became a Dame.","Tanni won a bronze medal in Seoul.","Tanni won two gold medals in Athens."],a=[2,4,1,3],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Tanni has used a wheelchair since she was seven.","Tanni won 16 Paralympic medals.","Tanni won the London Marathon wheelchair race once.","Tanni joined the House of Lords in 2010."],a=["T","T","F","T"],g=TF),
 dict(d="2d",k="short",m=1,q="What does the fact that Tanni “trained hard for many hours every week” tell you about her?",a="She was determined / dedicated and did not give up easily.",g="Accept determined, hard-working, committed or similar."),
 dict(d="2d",k="short",m=1,q="In paragraph 6, how did Tanni try to help disabled people? Give one way.",a="She spoke up for them so they could join in sport and everyday life; she wanted sport and everyday life to be open to more people.",g="Accept any one way."),
 dict(d="2g",k="mc",m=1,q="In paragraph 5, the author says Tanni set “more than 30 world records”. Why does the author include this fact?",opts=["To show how outstanding she was at her sport","To show how many races she entered","To show that her races were quite short","To explain how a racing chair is built"],a="A"),
 dict(d="2e",k="short",m=1,q="Imagine a young person with a disability meets Tanni. What might Tanni say to encourage them?",a="Something such as: with practice and determination, you can achieve great things.",g="Accept any sensible message linked to the final paragraph (courage, practice, determination, never giving up)."),
 dict(d="2c",k="mc",m=1,q="Which sentence best sums up the whole text?",opts=["Tanni Grey-Thompson was born in Cardiff in 1969.","A racing wheelchair has two large back wheels.","The Paralympic Games were held in Seoul in 1988.","Tanni Grey-Thompson became a great racer and then helped other people."],a="D"),
])
